(async()=>{
const SEL='input[type=checkbox][aria-label^="Seleccionar "]:not([aria-label^="Seleccionar la carpeta"]):not([aria-label="Seleccionar todos"])';
const ARCH='/admin?tab=documentos&vista=drive&sub=all';
const OTRA='/admin?tab=ajustes';
const sleep=ms=>new Promise(r=>setTimeout(r,ms));
const lt=[];
new PerformanceObserver(l=>{for(const e of l.getEntries())lt.push({s:e.startTime,d:e.duration})}).observe({type:'longtask'});
const ir=u=>{history.pushState(null,'',u);dispatchEvent(new PopStateEvent('popstate'))};
async function medir(){
 const t0=performance.now();const n0=performance.getEntriesByType('resource').length;
 ir(ARCH);let tPanel=null;
 while(!document.querySelector(SEL)){if(!tPanel&&document.querySelector('[data-qa=panel-archivo]'))tPanel=performance.now()-t0;await new Promise(r=>requestAnimationFrame(r));if(performance.now()-t0>30000)return{timeout:true};}
 const t1=performance.now()-t0;await sleep(2500);
 const res=performance.getEntriesByType('resource').slice(n0);
 const js=res.filter(r=>/\.js(\?|$)/.test(r.name));
 const lista=res.filter(r=>/\/api\/admin\/documents(\?|$)/.test(r.name)&&!/conteo=1/.test(r.name)).sort((a,b)=>b.responseEnd-a.responseEnd)[0];
 const tareas=lt.filter(x=>x.s>=t0-5&&x.s<=t0+t1+50);
 const despues=lt.filter(x=>x.s>t0+t1+50);
 return{tarjeta:Math.round(t1),panel:tPanel&&Math.round(tPanel),tareaMax:Math.round(Math.max(0,...tareas.map(x=>x.d))),tareasSuma:Math.round(tareas.reduce((a,x)=>a+x.d,0)),nTareas:tareas.length,tareasDespues:despues.map(x=>Math.round(x.d)),jsKB:Math.round(js.reduce((a,r)=>a+(r.decodedBodySize||0),0)/1024),jsN:js.length,listaFin:lista?Math.round(lista.responseEnd-t0):null,trasLista:lista?Math.round(t1-(lista.responseEnd-t0)):null,tarjetas:document.querySelectorAll(SEL).length};
}
const primera=await medir();const segundas=[];
for(let i=0;i<3;i++){ir(OTRA);await sleep(3000);segundas.push(await medir());}
const med=k=>{const v=segundas.map(s=>s[k]).filter(x=>typeof x==='number').sort((a,b)=>a-b);return v[Math.floor(v.length/2)]};
return JSON.stringify({primera,segunda:{tarjeta:med('tarjeta'),tareaMax:med('tareaMax'),tareasSuma:med('tareasSuma'),trasLista:med('trasLista'),jsKB:med('jsKB')},segundas});
})()
